#!/usr/bin/env python3
"""
Round 149b (culprits), 4 October 2026. Needs round 148b.

Takes out the Indigenous and Oil painting basemaps.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 149b (4 October)\n\nNeeds round 148b. No tiles patch. No app.js?v= bump.\n\n- Taken out at the owner's word: the Indigenous basemap (147i) and the Oil\n  painting basemap (148b). Their app.js blocks (INDIG, OIL, the oilbrush://\n  protocol and their basemapPanelHtml / setBasemap wrappers) and their test\n  blocks are gone. Hell and the other basemaps are unchanged.\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round149b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 148b" not in h.read_text(encoding="utf-8"):
        sys.exit("round149b: round 148b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round149b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round149b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round149b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
